"""Archive issue11 only after full-denominator analysis and replay QA pass."""
import csv,json,hashlib,re,shutil,gzip
from pathlib import Path
ROOT=Path('/root/gpufree-data/tw_stage1/issue11_20261110');DEST=Path('validation_artifacts/stage1_issue11_20261110');BASE=Path('validation_artifacts/stage1_issue10_20261109')

def pct(x):return 'NA' if x is None else f'{100*x:.4f}%'
def val(x):return 'NA' if x in [None,''] else f'{float(x):.3f}'
def interval(lo,hi):return '['+pct(lo)+','+pct(hi)+']'
def csvrows(name):return list(csv.DictReader((ROOT/name).open()))

def main():
 assert (ROOT/'analysis_and_replay_complete').exists() and (ROOT/'all_representative_replays_complete').exists() and (ROOT/'risk_analysis_complete').exists()
 for n in ['delivery_integrity_audit.json','video_quality_audit.json','video_physics_manual_audit.json','observer_equivalence_audit.json','raw_record_integrity_audit.json']:assert json.loads((ROOT/n).read_text())['passed'],n
 assert '\nOK\n' in (ROOT/'statistics_tests.log').read_text()
 decision=json.loads((ROOT/'concentration_decision.json').read_text());corners=json.loads((ROOT/'corner_diagnostics.json').read_text());overall=json.loads((ROOT/'overall_risks.json').read_text());cuts=json.loads((ROOT/'frozen_feature_cuts.json').read_text());raw=json.loads((ROOT/'raw_record_integrity_audit.json').read_text());recovery=json.loads((ROOT/'physical_recoverability_limits.json').read_text());reps=json.loads((ROOT/'representative_selection_summary.json').read_text())
 assert not decision['defaults_promoted'] and decision['acceptance_unchanged'] and len(reps)==4 and raw['all_trials']==61440
 DEST.mkdir(exist_ok=True)
 for p in ROOT.iterdir():
  if p.name.startswith('git_api_') or p.name in ['completion_requirement_audit.json','issue11_reply_body.md','push_receipt.json','issue_reply_receipt.json']:continue
  if p.is_file() and (p.suffix in ['.json','.csv','.md','.npz'] or p.suffix=='.log' and p.name!='archive.log'):shutil.copy2(p,DEST/p.name)
 for folder in ['traces','smoke','smoke_complete_rng','figures','videos']:shutil.copytree(ROOT/folder,DEST/folder,dirs_exist_ok=True)
 p=DEST/'all_push_records.csv';q=DEST/'all_push_records.csv.gz'
 raw=p.read_bytes()
 with q.open('wb') as out:
  with gzip.GzipFile(filename='',mode='wb',fileobj=out,mtime=0) as z:z.write(raw)
 assert gzip.decompress(q.read_bytes())==raw
 (DEST/'push_csv_compression_audit.json').write_text(json.dumps({'passed':True,'raw_csv_sha256':hashlib.sha256(raw).hexdigest(),'raw_bytes':len(raw),'gzip_sha256':hashlib.sha256(q.read_bytes()).hexdigest(),'gzip_bytes':q.stat().st_size,'format':'lossless gzip; full raw CSV remains remote'},indent=2));p.unlink()
 shutil.copy2(ROOT/'issue11_video_contact_sheet.png',DEST/'issue11_video_contact_sheet.png');shutil.copy2(BASE/'joint_colors.json',DEST/'joint_colors.json')
 manifest=json.loads((BASE/'sha256.json').read_text());references={};models=json.loads((ROOT/'input_models.json').read_text())
 for name,e in models.items():
  rel='models/'+name+'/'+Path(e['checkpoint']).name;p=BASE/rel;assert hashlib.sha256(p.read_bytes()).hexdigest()==manifest[rel]==e['sha256'];references[name]={'sha256':e['sha256'],'relative_link':'../'+BASE.name+'/'+rel,'actual_logged_updates':e['actual_logged_updates']}
 (DEST/'checkpoint_references.json').write_text(json.dumps(references,indent=2));ref=DEST/'baseline_sources';ref.mkdir(exist_ok=True)
 for name in ['all_evaluation_rates.csv','input_models.json']:
  assert hashlib.sha256((BASE/name).read_bytes()).hexdigest()==manifest[name];shutil.copy2(BASE/name,ref/name)
 lines=['# Issue #11: all-trial low-speed risk strata and extreme corners','','Issue: https://github.com/weiguang52/HUMANOID_TW/issues/11 . Base5fa8823. **Analysis only: no training and no policy/reward/randomization/default changes.**','','## Main conclusion','','Frozen primary-corner classification: **'+decision['classification']+'**. Overall measured-subset assessment: **'+decision['overall_measured_subset_assessment']+'**.',decision['next_single_recommendation']+'. This is the only proposed next step; it is NOT implemented.','','The classification is relative to the two measured, prospectively defined corners. It does not exclude every conceivable rare combination and does not prove a failed state is physically unrecoverable. Original acceptance criteria and the default configuration remain unchanged.','','## Cohort and observer validation','','Fixed requested training seeds1/2/3/4/5, each at1500 and4500 updates. Five-seed variance is conditional on the common parent. #7 protocol: bounded combined,1024environments, evaluation seeds1/2/3,0.3/0.5m/s,20s, deterministic policy, paired resets. Thirty jobs and61440 initial trials; every successful trial is retained in the denominators. Command indices0/1 match issue10. No checkpoint is selected by performance.','','The opt-in observer calls the original push sampler exactly once, adds no random draws or physics writes, and reuses the original first-failure recorder. The final64-env baseline-vs-expanded recheck includes complete NumPy cursor/Gaussian-cache fields and Python Gaussian-cache/version, not just principal RNG arrays. It showed bitwise-identical root/joint states, complete CPU/CUDA/NumPy/Python RNG and first-failure traces for both speeds. Initial preliminary smoke and complete recheck artifacts are both retained; the formal recorder class hash is unchanged, and formal evaluations do not enable the optional end-state audit helper. Nine tests cover fixed windows, censoring, post-failure exclusion, full denominators, outcome-blind bins and paired training-seed effects. See observer_equivalence_audit.json and statistics_tests.log. Each observing callback checks Torch RNG invariance. Baseline count agreement is recorded rather than substituted for new outcomes.','','## Original full-cohort fall rates','','| Updates | Speed | Falls / all trials | Mean over5seeds | SampleSD (pp) | Seed-bootstrap95% mean |','|---:|---|---:|---:|---:|---|']
 for stage in [1500,4500]:
  for command in ['forward_03','forward_05']:
   s=overall[f'{stage}:{command}'];lo,hi=s['seed_bootstrap95'];lines.append(f"| {stage} | {command} | {s['falls']}/{s['n']} | {pct(s['seed_equal_mean'])} | {100*s['seed_sample_sd']:.4f} | {interval(lo,hi)} |")
 lines+=['','Individual policy rates: policy_rates.csv. Within-policy Wilson intervals describe evaluation trials; seed-bootstrap intervals describe the five trained policies conditional on the fixed evaluation streams. Same mass/material draws are reused across models, so61440trials are not61440independent physical settings. See randomization_pairing_audit.json.','','## Two distinct risk units and raw records','','1. **20s initial-trial risk:** one initial environment/command, first true termination. Initial mass/friction/delay strata include all survivors and failures. After an automatic reset, that environment does not become a new independent trial.','2. **1s post-push risk:** every at-risk push with a full administrative1s followup. First failure in(0,1s] is an event; post-first-failure pushes are archived but excluded. Tail pushes after19s are excluded from this fixed-window risk. Intervening pushes/censoring are explicitly checked; none may be silently called a success.','',f"Recorded {raw['all_pushes']} total pushes and {raw['all_first_failures']} first-failure windows. Raw NPZ files include actual/nominal mass ratios for every link, every shape static/dynamic friction/restitution, shape-to-body mapping, initial and at-push delay, actual world/body delta-v, support feet/forces, contact-onset inferred phase, COM and foot states. CSVs: all_trial_records.csv and all_push_records.csv.gz (lossless gzip; full raw CSV remains remote). Raw integrity checks reconcile trial outcomes, first-failure traces, coordinate transforms, push bounds, delays and contact codes.",'','Frozen feature cuts (chosen from initial covariates without using outcomes):',f"- Base mass ratio quartiles: {cuts['mass']} (configuredU(.5,1.5)).",f"- Minimum assigned static friction over both foot shapes: {cuts['static']}.",f"- Corresponding dynamic-friction cuts: {cuts['dynamic']}.",f"- Actual3D push delta norm cuts: {cuts['push_amplitude']} from the square-uniform configured distribution.",'','Foot mass ratios and non-variation are in fixed_foot_mass_audit.json; a constant foot mass has no estimable effect. Static and dynamic friction are reported separately. Contact phase is inferred from measured contact onsets/previous periods, not an assumed commanded gait phase. Support codes:0flight,1left-only,2right-only,3double. Phase-bin0 means unavailable. Direction is forward/back when|dx|>=|dy|, side otherwise.','','## Full-denominator stratified risks and factor effects','','Tables include empty cells as NA, not zero risk, and flag n<30. Marginal factors: static/dynamic friction quartile, base mass quartile,0/20ms delay; push tables additionally include amplitude quartile, direction, support and contact phase. Full joint tables cross static-friction/mass/delay, with amplitude/direction/support for push windows. The dynamic-friction factor is secondary rather than silently substituted for static.','','- trial_stratified_risks.csv and trial_joint_strata.csv: full20s trial denominators, falls, Wilson95%, exposure/failure fractions and descriptive relative risk versus the cohort.','- push_stratified_risks.csv and push_joint_strata.csv: at-risk1s push-window denominators, successes included, same measures.','- factor_effects.csv and factor_seed_effects.json: explicit reference levels, equal-weight mean seed risks, risk differences/relative risks and jointly resampled seed-bootstrap intervals. Reference quartile2 for mass/friction, delay0; push references amplitudeQ1, forward, double support, phaseQ1. Zero/sparse reference effects are explicitly not estimable.','- stage_joint_comparison.csv: same full joint cells side by side with both denominators/Wilson intervals and descriptive changes; empty cells remain NA.','- stage_stratum_comparison.csv:4500-minus1500 changes under the SAME cuts and references, with paired seed-index intervals and common-exposure limitations.','','These are unadjusted observational associations, not independent adjusted causal effects. Joint tables expose confounding and sparse combinations; no regression or test of causal recoverability is claimed. Wilson intervals assume Bernoulli independence and can be too narrow for repeated pushes/shared draws. Training-seed intervals use all5^5=3125joint resamples, not3125new seeds; five-seed tails are uncertain, material-bucket/evaluation-stream uncertainty is not fully represented, and multiple exploratory comparisons have no simultaneous95% guarantee.','','Selected4500 low-speed factor contrasts (all full tables remain available):','','| Unit | Factor/target vs reference | Target n | Ref n | Equal-seed RR | Seed-bootstrap95% RR | Equal-seed risk difference (pp) |','|---|---|---:|---:|---:|---|---:|']
 for x in csvrows('factor_effects.csv'):
  if x['stage']=='4500' and x['command']=='forward_03' and ((x['unit']=='20s_trial' and x['factor'] in ['static_q','mass_q','delay_ms']) or (x['unit']=='1s_push_window' and x['factor'] in ['amplitude_q','support_code','direction'])):
   rrci='NA' if x['rr_seed_boot95_low']=='' else '['+val(x['rr_seed_boot95_low'])+','+val(x['rr_seed_boot95_high'])+']';rd='NA' if x['seed_mean_risk_difference']=='' else f"{100*float(x['seed_mean_risk_difference']):+.4f}"
   lines.append(f"| {x['unit']} | {x['factor']} {x['target_level']} vs {x['reference_level']} | {x['target_n']} | {x['reference_n']} | {val(x['seed_mean_relative_risk'])} | {rrci} | {rd} |")
 lines+=['','![Baseline trial risks](figures/baseline_trial_risks.png)','','![Push-window risks](figures/push_window_risks.png)','','![Joint risks with all denominators](figures/joint_baseline_heatmap.png)','','![Seed-level factor contrasts](figures/factor_seed_effects.png)','','## Predefined extreme corners and whole-trial exclusion','','STRICT: staticQ1 AND baseQ4 AND20ms AND body-forward delta>=.3m/s AND single support. ENVELOPE: (staticQ1 OR dynamicQ1) AND base(Q1 OR Q4) AND20ms AND amplitudeQ4 AND single support. Numeric cuts were derived only from covariates under the frozen rule. No best-looking corner was selected after failures.','','Concentration requires ENVELOPE trial coverage<=20% AND at least80% of low-speed first failures within1s of an eligible corner push. Case co-occurrence and proximal association are reported separately.','','| Updates | Corner | Exposed / all trials | Coverage | Proximal failures / all failures | Proximal share | Remaining20s falls / trials | Remaining risk + Wilson95% |','|---:|---|---:|---:|---:|---:|---:|---|']
 for stage in [1500,4500]:
  c=corners[f'{stage}:forward_03']
  for corner in ['strict','envelope']:
   e=c[corner];rr=e['remaining_trial_risk'];lines.append(f"| {stage} | {corner} | {e['exposed_trials']}/{c['all_trials']} | {pct(e['trial_coverage'])} | {e['proximal_failures']}/{c['all_failures']} | {pct(e['proximal_failure_fraction'])} | {rr['falls']}/{rr['n']} | {pct(rr['rate'])} {interval(rr['wilson95_low'],rr['wilson95_high'])} |")
 secondary=json.loads((ROOT/'secondary_concentration_cv.json').read_text())
 lines+=['','Secondary held-out-training-seed concentration sensitivity (fixed after partial record acquisition, before stratified outcome analysis):','','| Candidate cells | Held-out exposed / trials | Coverage | Captured / ALL first failures | Capture | <=20%coverage and>=80%capture |','|---|---:|---:|---:|---:|---|']
 for unit,e in secondary.items():lines.append(f"| {unit} | {e['exposed_trials']}/{e['all_trials']} | {pct(e['held_out_trial_coverage'])} | {e['captured_first_failures']}/{e['all_first_failures']} | {pct(e['held_out_failure_capture'])} | {e['secondary_concentration_detected']} |")
 lines+=['','For each held-out seed, cells are ranked using only the other four seeds, min20training observations, with a union-of-trials20% training coverage budget. Push-cell budgets also count unique initial trials. This guards against declaring global spread solely because a narrow primary mask failed. Folds overlap and share physical evaluation streams; it is a secondary diagnostic, not independent confirmation. Selected cells and full rules: secondary_concentration_cv.json and frozen_secondary_concentration.md.']
 lines+=['','Both speeds, per-seed sensitivities, sparse corner push risks, co-occurring failures and seed-bootstrap failure coverage are in corner_diagnostics.json. **Exclusion removes whole exposed trials, including successes; it does not remove only cases.** Exposure membership depends on surviving until a push, so complement risks are descriptive selection analyses, not counterfactual improvements and not acceptance replacements. Late pushes excluded by administrative followup are reported. Zero observed corner failures with few exposures do not establish safety.','','![Corner coverage and diagnostic exclusion](figures/corner_diagnostics.png)','','## 1500vs4500 failure patterns','','failure_mode_comparison.csv compares low-speed case composition under common delay/direction/support labels. These case shares are not risk estimates; denominators are in the stratified risk tables. A mode not seen in this sample is not proven eliminated. Common baseline strata allow comparison, but support/phase are policy-dependent states, so within-push-stratum changes are not randomized causal mediation effects.' ]
 mode_changes=csvrows('failure_mode_changes.csv');ranked=sorted(mode_changes,key=lambda r:int(r['case_count_change4500_minus1500']));chosen=[]
 for x in ranked[:3]+ranked[-3:]:
  if x not in chosen:chosen.append(x)
 lines+=['','Largest observed mode decreases/increases (same labels, all initial-trial denominators fixed; push-window exposure can differ):','','| Case mode |1500 cases |4500 cases | Change |1500 push events/n |4500 push events/n |','|---|---:|---:|---:|---:|---:|']
 for x in chosen:lines.append(f"| {x['case_mode']} | {x['case_count1500']} | {x['case_count4500']} | {int(x['case_count_change4500_minus1500']):+d} | {x['push_events1500']}/{x['push_n1500']} | {x['push_events4500']}/{x['push_n4500']} |")
 lines+=['','Full same-mode counts, exposure risks and intervals are in failure_mode_changes.csv. A0/0 push denominator for no_recent_push means not applicable, not zero risk; that label is case composition only. An observed zero in4500 is not proof that training eliminated a physical mechanism.']
 mechanism=json.loads((ROOT/'failure_mechanism_summary.json').read_text())
 lines+=['','| Updates | Speed | First failures | Terminal sagittal share | Recent<=1s push share | Both |','|---:|---|---:|---:|---:|---:|']
 for key,m in mechanism.items():
  stage,command=key.split(':');lines.append(f"| {stage} | {command} | {m['first_failures']} | {pct(m['sagittal_terminal_fraction'])} | {pct(m['recent_push_fraction'])} | {pct(m['recent_push_and_sagittal_fraction'])} |")
 lines+=['','![Case composition comparison](figures/failure_mode_comparison.png)','','## Physical recoverability: what these records can establish','','| Updates | Low-speed failures | Failures with another-seed success under identical initial mass/friction/delay | Fraction | Initial-draw groups where all5seeds fail |','|---:|---:|---:|---:|---:|']
 for stage in [1500,4500]:
  e=recovery[str(stage)];lines.append(f"| {stage} | {e['failed_trials']} | {e['failures_whose_identical_initial_mass_friction_delay_has_another_seed_success']} | {pct(e['fraction'])} | {e['all5_training_seeds_fail_same_initial_draw_groups']} |")
 lines+=['','Identical initial physical draws succeeding in another policy refute only that baseline randomization alone is universally impossible. Actual push streams, COM states and phases can differ, so this is not proof that the exact failed compound state is recoverable. physical_stress_summary.csv reports successful/failed-window COM/foot-center capture-distance and friction-limited stopping-distance descriptors. The capture estimate uses pre-push whole-bodyCOM velocity plus actual root delta; instantaneous foot centers omit finite feet and future foot placement. Stopping estimates assume horizontal constant mu*g and conservative supporting-foot dynamic friction. Walking, angular momentum, joint/actuator limits and alternative recovery controllers are not solved. **Observed policy failure cannot establish physical unrecoverability; the records do not justify labeling a subset physically impossible.** See physical_recoverability_limits.json.','','## Exact representative low-speed failure replays','','The original two highest-count coarse4500 low-speed case strata and the two highest-event-count full static/mass/delay/amplitude/direction/support strata are shown; successful pushes stay in their risk denominators. The two additional full-joint examples are specified before stratified outcome analysis in representative_selection_addendum.md; sparse cells remain visible with denominators and are not promoted into general risk claims. Selection is deterministic (nearest median stratum amplitude, then seed/eval/env/step; no-recent-push uses earliest failure). These are EXACT recorded pre-reset root/joint states, not a fresh1env policy rollout or a counterfactual controller. The camera follows translation and heading. Original physics/non-material relationships and1876attributes are preserved in the precoloredUSD; no runtime material binding. Joint legend:joint_colors.json.','']
 for i,e in enumerate(reps,1):
  t=e['trial_baseline'];p=e['push_features'];lines+=['',f"### Representative{i}: {e['mode']}",f"Model {e['model']}, eval seed{e['eval_seed']}, env{e['env_id']}, first failure step{e['failure_step']}. Case stratum count/share: {e['mode_failure_count']} / {pct(e['mode_failure_share'])}; eligible push-window events/n: {e['eligible_push_events']}/{e['eligible_push_denominator']} (case counts above are a distinct unit). Base ratio={t['base_mass_ratio']:.6f}, foot static min={t['foot_static_min']:.6f}, dynamic min={t['foot_dynamic_min']:.6f}, initial delay={t['delay_ms']}ms."]
  if p:lines.append(f"Actual body delta-v=({p['delta_body_x']:+.6f},{p['delta_body_y']:+.6f},{p['delta_body_z']:+.6f})m/s; support={p['support_code']}, phases=({p['left_cycle_phase']:.4f},{p['right_cycle_phase']:.4f}); source row={p['source_push_row']}.")
  lines.append(f"[Front](videos/mode{i}_front.mp4) | [Side](videos/mode{i}_side.mp4) | [Selection/source](representative_mode{i}.json)")
 lines+=['','Each replay contains up to51inclusive pre-reset samples at50fps (about1s), not a20s acceptance video. Joint velocity is zero for display and physics is not integrated. Encoding/frame/source-state/color/framing and manual attachment audits accompany the files. Stage1 velocity commands have no HumanML3D sourceNPY (N/A); no synthetic source motion is invented.','','## Provenance and tracking','','All10 input checkpoints already exist in the issue10 versioned bundle and are linked by verified SHA in checkpoint_references.json; no new models were trained. Original raw logs/records remain remotely, archive logs strip ANSI/trailing whitespace. No mounted data is copied to local storage. Default training/evaluation configurations are unchanged except opt-in observational hooks.','','Notion replaces Linear: https://www.notion.so/403325d8231d8172995bf19510b8d760 . Issue reply records the conclusion, original/complement risks, physical limits and exactly one unimplemented next recommendation.']
 lines.insert(6,(ROOT/'interpretation.md').read_text().strip())
 (DEST/'README.md').write_text('\n'.join(lines)+'\n')
 for p in DEST.rglob('*.log'):
  s=re.sub(r'\x1b\[[0-9;?]*[A-Za-z]','',p.read_text(errors='replace'));p.write_text('\n'.join(x.rstrip() for x in s.splitlines()).rstrip()+'\n')
 manifest={str(p.relative_to(DEST)):hashlib.sha256(p.read_bytes()).hexdigest() for p in DEST.rglob('*') if p.is_file() and p.name!='sha256.json'};(DEST/'sha256.json').write_text(json.dumps(manifest,indent=2));print('ARCHIVED',len(manifest),'files; CLASSIFICATION',decision['classification'])
if __name__=='__main__':main()
